  "Order": "Ajaja",
  "Each part’s warranty is on its label and invoice; bring the order number with the part.": "Wabiin kutaa tokkoon tokkoo mallattoo fi nagahee isaa irra jira; lakkoofsa ajajaa kutaa sana waliin fidaa.",
  "Repairs are covered from the day you collect the phone. Bring this ticket.": "Suphaan guyyaa bilbila keessan fudhattan irraa eegalee wabii qaba. Tikeetii kana fidaa.",
  "We can’t find that number on this account. Check it, or send it to us on WhatsApp and we look it up.": "Lakkoofsa sana herrega kana irratti hin arganne. Ilaalaa, ykn WhatsApp irratti nuuf ergaa nu ni barbaanna.",
  "This browser cannot scan codes. Type the number instead.": "Barbaadaan kun koodii dubbisuu hin danda'u. Lakkoofsa barreessaa.",
