  "Approved. Sign in and the shop shows your trade price on every part.": "Mirkanaa'eera. Seenaa gatii daldalaa keessan kutaa hunda irratti ni argitu.",
  "We reply by e-mail and WhatsApp, usually within one working day. Sign in with the same e-mail to see the result here.": "Imeelii fi WhatsApp irratti deebisna, yeroo baay'ee guyyaa hojii tokko keessatti. Bu'aa asitti arguuf imeelii sanaan seenaa.",
