  "HOW WE SHIP": "Akkamitti akka ergine",
  "Typical times for planning. Every shipment is quoted with its own time and price.": "Yeroo baratamaa karoorfachuuf. Ergaan tokkoon tokkoo yeroo fi gatii mataa isaa qaba.",
  "CUSTOMS NOTES": "Yaadannoo kastamii",
