  "Every week, out of Dubai.": "Torbee hunda, Dubai irraa.",
  "Planes on the air routes, ships on the sea lanes. Pick a region to see how we ship there.": "Xiyyaarri karaa qilleensaa irra, markabni karaa galaanaa irra. Naannoo filadhaa akkamitti akka ergine ilaalaa.",
  "SHIPPING QUOTE": "Gatii ergaa",
