  "Levels and thresholds are samples until the owner confirms them.": "Sadarkaaleen fi daangaan hanga abbaan qabeenyaa mirkaneessutti fakkeenya.",
  "PENDING": "Eegaa jira",
  "System ready.": "Sirni qophaa'eera.",
