  "Display, touch, True Tone and battery.": "Agarsiisa, tuqaa, True Tone fi baatirii.",
  "ASK SAMSOOM": "SAMSOOM GAAFADHU",
  "Not sure which part?": "Kutaa kam akka ta’e hin beektu?",
  "Tell me the model, I find the part.": "Moodeela natti himi, kutaa nan argadha.",
  "Ask now": "Amma gaafadhu",
  "High-grade copy · very good color and touch · lower price": "Kooppii sadarkaa olaanaa · halluu fi tuqaa gaarii · gatii gadi",
  "LCD with built-in touch · good everyday quality · budget friendly": "LCD tuqaa of keessaa qabu · qulqullina guyyaa gaarii · gatii salphaa",
  "Talk to our team": "Garee keenya haasofsiisi",
