  "Chat with our team. Open WhatsApp on this device, or scan the code with your phone.": "Garee keenya waliin haasa’i. Meeshaa kana irratti WhatsApp bani ykn koodii bilbilaan iskaanii.",
  "Add our number in WeChat and send us a message. We reply in Arabic, English and Chinese.": "Lakkoofsa keenya WeChat irratti dabaliitii nuuf ergi. Afaan Arabaa, Ingiliffaa fi Chaayinaatiin deebisna.",
  "Chat with us": "Nu waliin haasa’i",
