  "Levels": "Sadarkaalee",
  "IN STOCK · DEIRA": "KUUSAA KEESSA · DEIRA",
  "Screens, batteries, cameras, flex and more, tested before they ship.": "Iskiriinota, baatirii, kaameraa, fileeksii fi kkf, osoo hin ergamin qoratamoo.",
  'WORLDWIDE SHIPPING': 'ERGAMSA ADDUNYAA',
  'to your door.': 'hanga balbala keessanii.',
  'We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.': 'Torban torbaniin suuqota suphaa fi daldaltoota Baha Giddugaleessaa, Afrikaa, Awurooppaa fi Eeshiyaa keessaa jiraniif kutaalee ergina: hiriyoota keenyaan balbalaa hanga balbalaatti, ykn ergaa keessaniin.',
  'Weekly': 'Torbanitti',
  'departures': 'ergamsa',
  'Door to door': 'Balbalaa hanga balbalaa',
  'tracked and insured': 'hordofamaa fi inshuraansii qabu',
  'Your shipper': 'Ergaa keessan',
  'welcome too': 'isas ni simatu',
  'WHERE WE SHIP': 'EESSATTI ERGINA',
  'Pick a region, then tap a country to see how we get there and how long it takes.': 'Naannoo filadhaa, achii akkamitti fi yeroo meeqa keessatti akka geenyu ilaaluuf biyya tuqaa.',
  'Tap a country for times': 'Yeroo ilaaluuf biyya tuqaa',
  'Get a quote': 'Gatii gaafadhaa',
  'Same day to four weeks: you choose.': 'Guyyuma sana irraa hanga torban afurii: isin filadhaa.',
  'Every way we ship, on one line. Urgent parts fly; big orders sail.': 'Karaalee ergaa hunda sarara tokko irratti. Kutaaleen ariifachiisoon xiyyaaraan, ajajni gurguddaan bishaaniin.',
  'Collect in Deira': 'Deira irraa fudhachuu',
  'You or your agent picks it up at our counter, same day.': 'Isin ykn bakka buʼaan keessan guyyuma sana kaawuntara keenya irraa fudhattu.',
  'Express courier': 'Koriyara saffisaa',
  'Door to door with DHL, UPS, FedEx or Aramex. Urgent parts.': 'DHL, UPS, FedEx ykn Aramex’n balbalaa hanga balbalaa. Kutaalee ariifachiisoo.',
  'Road freight': 'Geejjiba karaa lafaa',
  'By truck to Saudi Arabia, Oman and the Gulf.': 'Konkolaataa fe’umsaatiin Saawud Arabiyaa, Omaan fi Galoo Arabaatti.',
  'Air cargo': 'Fe’umsa qilleensaa',
  'Bulk orders to the main airports, best price per kilo.': 'Ajajni gurguddaan buufata xiyyaaraa gurguddootti, gatii kiiloo tokkoo gaarii.',
  'About a week': 'Torban tokko naannoo',
  'Sea freight': 'Geejjiba galaanaa',
  'Large orders by container, via Suez or East Africa.': 'Ajajni gurguddaan konteenaraan, karaa Suweez ykn Afrikaa Bahaa.',
  'A commercial invoice and packing list go with every shipment.': 'Ergaa hunda wajjin nagaheen daldalaa fi tarreeffamni qindaa’inaa ni deema.',
  'Duties and taxes are paid by the receiver on arrival, unless we agree otherwise.': 'Yoo waliigaltee biraa hin qabaanne, taaksii fi gibira yeroo gahu fudhataan kaffala.',
  'Some routes need the importer’s company registration for clearance; we tell you before we ship.': 'Karaaleen tokko tokko qulqulleessuuf galmee dhaabbata galchaa barbaadu; osoo hin ergin isinitti himna.',
  'Courier, air, road or sea: the best for your parts.': 'Koriyara, qilleensa, karaa lafaa ykn galaana: kan kutaalee keessaniif gaarii ta’e.',
  'It opens WhatsApp with your request, neatly laid out.': 'WhatsApp gaaffii keessan sirnaan qindaa’e wajjin bana.',
  'Shipping, time and paperwork, before you pay.': 'Ergaa, yeroo fi waraqaalee, osoo hin kaffalin.',
  'We pick the route': 'Karaa ni filanna',
  'You get one price': 'Gatii tokko argattu',
  'You send the form': 'Unka ni ergitu',
