  'See every country': 'Biyyoota hunda ilaali',
  'Our home market: next-day to the Gulf, a few days to the Levant.': 'Gabaa keenya: Galoo Arabaatti guyyaa itti aanu, Leevaantitti guyyoota muraasa.',
  'From London to Kyiv: express, air cargo or sea via Suez.': 'Landan hanga Kiyeevitti: saffisaa, fe’umsa qilleensaa ykn galaana karaa Suweez.',
  'North, East and West Africa by courier, cargo or sea.': 'Afrikaa Kaabaa, Bahaa fi Lixaa koriyaraan, fe’umsaan ykn galaanaan.',
