  'Search, your devices, deals and the filters that narrow every grade.': 'Barbaacha, meeshaalee kee, gatii hir’isaa fi calaltuu sadarkaa hundaa.',
  'Orders, points, your card, companies and settings.': 'Ajajawwan, qabxiiwwan, kaardii kee, dhaabbilee fi qindaa’ina.',
