  'Everything on this website and in its systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by the copyright laws of the United Arab Emirates, including Federal Decree-Law No. 38 of 2021. A screenshot for your own reference is fine; copying, sharing or publishing it without our written permission is not.': 'Wanti marsariitii kanaa fi sirnoota isaa irra jiru hundi (suuraa, dizaayinii, barreeffama, gatii fi daataa) kan Sam Electronics ti, seerota mirga abbummaa UAE, Labsii-Seeraa Federaalaa Lak. 38 bara 2021 dabalatee, eegama. Suuraa iskiriinii ofiif fudhachuun rakkoo hin qabu; hayyama barreeffamaa keenya malee garagalchuu, qooduu ykn maxxansuun hin hayyamamu.',
  'Your connection says you are somewhere else than your device does. Prices, stock and delivery here depend on where you really are, and hiding your location goes against our terms of use. Please switch the VPN off for real prices and delivery times.': 'Walqunnamtiin kee bakka meeshaa kee irraa adda ta’e agarsiisa. Gatiin, kuusaa fi geejjibni bakka dhugaan jirtu irratti hundaa’a, bakka dhoksuunis haalawwan fayyadamaa keenyaa faallessa. Gatii fi yeroo dhugaa argachuuf VPN cufi.',
  'Prices and delivery depend on where you really are. Please switch the VPN off.': 'Gatiin fi geejjibni bakka dhugaan jirtu irratti hundaa’a. Mee VPN cufi.',
  'Why am I seeing this?': 'Maaliif kana arga?',
  'Keeping it for yourself is fine; sharing or publishing it needs our permission.': 'Ofiif qabachuun rakkoo hin qabu; qooduuf ykn maxxansuuf hayyama keenya barbaachisa.',
  'Read the full notice': 'Beeksisa guutuu dubbisi',
