  'Site notices': 'Beeksisa marsariitii',
  'Short pop-ups.': 'Foddaawwan gagabaaboo.',
  'The full story.': 'Seenaa guutuu.',
  'What each notice on this website means, and every notice this device has been shown.': 'Beeksisni tokkoon tokkoon maal akka jedhu, fi beeksisa meeshaan kun agarsiifame hunda.',
  'Location notice (VPN)': 'Beeksisa bakkaa (VPN)',
  'Notices shown on this device': 'Beeksisa meeshaa kana irratti agarsiifaman',
  'None so far.': 'Hanga ammaatti hin jiru.',
  'This list stays on this device. The team keeps the same record with your customer ID.': 'Tarreen kun meeshaa kana irra hafa. Gareen galmee wal fakkaatu ID maamilaa kee waliin qabata.',
  'Location mismatch (VPN)': 'Bakki wal hin simu (VPN)',
