  'Part and fitting, with the time it takes': 'Kutaa fi maxxansuu, yeroo fudhatu waliin',
  'Reads photos': 'Suuraa dubbisa',
  'A screenshot of Settings → About, or the box label': 'Iskiriinshootii Settings → About, ykn mallattoo saanduqaa',
  'Hands you to a person': 'Nama waliin si quunnamsiisa',
  'The team on WhatsApp or WeChat, with your chat': 'Garee WhatsApp ykn WeChat irra, haasawa kee waliin',
  'Send Samsoom a screenshot': 'Samsoom’f iskiriinshootii ergi',
  'Send a photo': 'Suuraa ergi',
  'Photo ready: Samsoom will read the model on it': 'Suuraan qophii dha: Samsoom moodeela irratti dubbisa',
  'Listening…': 'Dhaggeeffachaa jira…',
  'Speak your question': 'Gaaffii kee dubbadhu',
  'Helpful': 'Gargaaraa',
  'Not helpful': 'Hin gargaaru',
  'Find a part': 'Kutaa barbaadi',
  'Repair price': 'Gatii suphaa',
  'My phone won’t charge': 'Bilbilli koo hin chaarjii ta’u',
  'My phone is not charging, what should I do?': 'Bilbilli koo hin chaarjii ta’u, maal godhu?',
  'Do you ship worldwide?': 'Addunyaa guutuutti ni ergituu?',
  'Fitting price': 'Gatii maxxansuu waliin',
  'How much with fitting?': 'Maxxansuu waliin meeqa?',
  'The cheapest one': 'Isa rakasaa',
  'Which is the cheapest?': 'Kamtu rakasaa dha?',
  'Where are you?': 'Eessa jirtu?',
  'Open on Friday?': 'Jimaata banaa?',
  'Are you open on Friday?': 'Jimaata banaa dha?',
  'How can I contact you?': 'Akkamitti isin quunnamuu danda’a?',
  'Tell me a joke': 'Qoosaa natti himi',
  'iPhone 13 screen fitted': 'Iskiriinii iPhone 13 maxxanfame',
  'iPhone 13 screen repair price': 'Gatii suphaa iskiriinii iPhone 13',
  'I read your photo: it is a': 'Suuraa kee dubbiseera: kun',
  'I can see an IMEI number on the photo. Send it to the team on WhatsApp and they will find the exact model.': 'Suuraa irratti lakkoofsa IMEI nan arga. Garee WhatsApp irratti ergi, moodeela sirrii ni argatu.',
  'I looked closely but couldn’t read a model on this photo. A screenshot of Settings → About phone works best, or just tell me the model.': 'Of eeggannoon ilaale, garuu suuraa kana irratti moodeela dubbisuu hin dandeenye. Iskiriinshootiin Settings → About phone caalaa hojjeta, yookaan moodeela natti himi.',
  'I can read text on photos, but I couldn’t find a model on this one. Try the label on the box, or type the model, and I’ll take it from there.': 'Barreeffama suuraa irraa dubbisuu nan danda’a, garuu kana irratti moodeela hin arganne. Mallattoo saanduqaa yaali, yookaan moodeela barreessi, kan hafe ani nan qabadha.',
  'Send me a photo with the camera button: a screenshot of Settings → About phone, or the label on the box, works best. I’ll read the model for you.': 'Qabduu kaameraatiin suuraa naaf ergi: iskiriinshootiin Settings → About phone ykn mallattoon saanduqaa caalaa gaarii dha. Moodeela siif nan dubbisa.',
  'Settings → About phone → Model.': 'Settings → About phone → Moodeela.',
  'Settings → About phone → All specs → Model.': 'Settings → About phone → All specs → Moodeela.',
  'Dial *#06# for the IMEI and send it to us: we find the exact model.': 'IMEI argachuuf *#06# bilbili nuuf ergi: moodeela sirrii ni arganna.',
  'Still about your': 'Ammas waa’ee',
  'Tell me the part: screen, battery, camera or charging port.': 'Kutaa natti himi: iskiriinii, baatirii, kaameraa ykn karra chaarjii.',
  'Sure, for which model?': 'Dhugaadha, moodeela kamiif?',
  'Tell me the model and I’ll find it.': 'Moodeela natti himi, nan argadha.',
  'Which one are you after?': 'Kam barbaadda?',
  'good news, we have these': 'oduu gaarii, kanneen qabna',
  'this is on our shelf': 'kun hiddii keenya irra jira',
  'Tap + to add one to your cart.': 'Gaarii keessatti dabaluuf + tuqi.',
  'Want it fitted? Ask me for the repair price.': 'Akka maxxanfamu barbaaddaa? Gatii suphaa na gaafadhu.',
  'We’re in Al Murar, Deira, Dubai.': 'Nuti Al Murar, Deira, Dubaayitti argamna.',
  'Tap below for the map and directions.': 'Kaartaa fi kallattiif gadi tuqi.',
  'Call the shop, message us on WhatsApp or WeChat, or e-mail us. We’re @samelectronics.uae on Instagram, TikTok and Facebook.': 'Suuqii bilbili, WhatsApp ykn WeChat irratti ergaa nuuf ergi, ykn imeelii nuuf barreessi. Instagram, TikTok fi Facebook irratti @samelectronics.uae dha.',
  'Every part has a warranty that depends on the grade:': 'Kutaan hundi wabii sadarkaa irratti hundaa’e qaba:',
  'Tell me the model and the part, like “A54 battery” or “iPhone 13 screen”, and I’ll show the price of each grade.': 'Moodeelaa fi kutaa natti himi, fakkeenyaaf “A54 baatirii” ykn “iPhone 13 iskiriinii”, gatii sadarkaa tokkoon tokkoon siif agarsiisa.',
  'The dirham is pegged to the dollar, so this rate stays the same.': 'Dirhamni doolaraan hidhamee jira, kanaaf saffisni kun hin jijjiiramu.',
  'That makes': 'Kun',
  'The answer is': 'Deebiin',
  'Easy:': 'Salphaa:',
  'month': 'ji’a',
  'Are you open now?': 'Amma banaa dha?',
  'Are you open?': 'Banaa dha?',
  'Ask me anything.': 'Waan barbaadde na gaafadhu.',
  'Brands & grades': 'Maqaalee fi sadarkaalee',
  'Charging flex': 'Fileeksii chaarjii',
  'Chats': 'Haasawa',
  'Delete': 'Haqi',
  'Rename': 'Maqaa jijjiiri',
  'Copy': 'Garagalchi',
  'Do you have the Galaxy A54 screen in Service Pack?': 'Iskiriinii Galaxy A54 Service Pack qabduu?',
  'Do you ship to Nigeria?': 'Naayijeeriyaatti ni ergituu?',
  'Grades': 'Sadarkaalee',
  'Here is what I found in stock': 'Kuusaa keessaa kanan argadhe kunoo',
  'How much to fit an iPhone 13 battery?': 'Baatirii iPhone 13 maxxansuuf meeqa?',
  'Message Samsoom': 'Samsoom’f ergaa',
  'Message Samsoom…': 'Samsoom’f ergaa…',
  'Opening hours': 'Sa’aatii banamuu',
  'Opening hours & directions': 'Sa’aatii fi kallattii',
  'Parts, grades, prices, repairs, shipping, opening hours: I know the shop inside out. Spelling mistakes are fine, and I speak your language.': 'Kutaalee, sadarkaalee, gatii, suphaa, ergaa, sa’aatii: suuqii guutummaan nan beeka. Dogoggorri barreeffamaa rakkoo miti, afaan kees nan dubbadha.',
  'Right now:': 'Amma:',
  'Sam Circuit': 'Sam Circuit',
  'Samsoom can make mistakes. Prices and stock are confirmed by the team on WhatsApp.': 'Samsoom dogoggoruu danda’a. Gatii fi kuusaa gareen WhatsApp irratti mirkaneessa.',
  'Trade prices unlock once your trade account is approved. Send a bulk list and we quote it the same day.': 'Gatiin jumlaa herregni daldalaa kee yeroo mirkanaa’u ni banama. Tarree jumlaa ergi, guyyuma sana gatii siif kennina.',
  'What is the difference between Original, OLED and Incell?': 'Garaagarummaan Original, OLED fi Incell maali?',
  'WhatsApp the team': 'Garee WhatsApp irratti',
  'Which grade?': 'Sadarkaa kam?',
  'Worldwide shipping': 'Ergaa addunyaa',
  'You': 'Ati',
  'Your chats': 'Haasawa kee',
  'Your conversations will appear here.': 'Haasawni kee as mul’ata.',
  'and': 'fi',
  'grade': 'sadarkaa',
  'grades': 'sadarkaalee',
