  'We ship from Deira every day to the Middle East, Africa, Europe and Asia. Every order is tracked and securely packed; shipping is quoted with your order.': 'Guyyaa guyyaan Deira irraa Baha Giddugaleessa, Afrikaa, Awurooppaa fi Eeshiyaatti ergina. Ajajni hundi ni hordofama, nageenyaan kuufama; gatiin ergaa ajaja kee waliin kenname.',
