  'Securely packed by hand': 'Harkaan nageenyaan kuufame',
  'Quoted with your order': 'Ajaja kee waliin gatiin kenname',
  'Trade prices for repair shops and resellers once your trade account is approved. Send a bulk list and we quote it the same day.': 'Gatii jumlaa suuqii suphaa fi gurgurtootaaf, erga herregni daldalaa mirkanaa’ee. Tarree jumlaa ergi, guyyuma sana gatii kennina.',
  'Our bench in Deira replaces screens and batteries and fixes board faults. Every repair is tested before you collect it.': 'Minjaalli keenya Deiraatti iskiriinii fi baatirii jijjiira, dogoggora boordiis ni sirreessa. Suphaan hundi osoo hin fudhatin qoratama.',
