  'Depends on your budget. Every grade is labelled on your order:': 'Baajata kee irratti hundaa’a. Sadarkaan hundi ajaja kee irratti barreeffama:',
  'Yes, for approved trade accounts. Prices step down as your order grows:': 'Eeyyee, herrega daldalaa mirkanaa’eef. Ajajni kee yeroo guddatu gatiin gadi bu’a:',
