  'This part of the site is still being built. Everything you need is on the home page in the meantime.': 'Kutaan marsariitii kanaa ammallee ijaaramaa jira. Hanga sanaatti wanti si barbaachisu hundi fuula jalqabaa irra jira.',
  'Open Find My Part': 'Kutaa koo barbaadi bani',
