  'The big box plays our latest offers. Pick a tab, a part or a brand and it shows that topic\'s own deals.': 'Saanduqni guddaan dhiyeessii haaraa agarsiisa. Tab, kutaa ykn birandii filadhu, dhiyeessii isaa agarsiisa.',
  'The coloured tag is the quality (Original, OLED, Incell, AAA and more). The dark tag with a light is who made it.': 'Mallattoon halluu qabu qulqullina (Original, OLED, Incell, AAA fi kkf). Kan dukkanaa’aa ifa qabu oomishaa dha.',
  'Star a part to keep it in My Bench. The two-cards button adds it to Compare: up to three parts side by side.': 'Kutaa urjiin mallatteessuun My Bench keessa kaa’i. Furtuun kaardii lamaa gara wal bira qabuutti dabala: hanga kutaa sadii.',
  'Sort by price, newest or best match, and switch between the grid and the list.': 'Gatii, haaraa ykn walsimannaa gaariin tartiibessi; giriidii fi tarree jidduu jijjiiri.',
  'Repair shops and traders: apply once, and every part shows your trade price.': 'Suuqonni suphaa fi daldaltoonni: al tokko iyyadhaa, kutaan hundi gatii daldalaa keessan agarsiisa.',
  'The questions people ask most, answered in one place. Still stuck? Ask Samsoom.': 'Gaaffiiwwan baay’ee gaafataman bakka tokkotti. Ammas? Samsoom gaafadhu.',
