  'Charging board': 'Boordii chaarjii',
  'Loudspeaker': 'Sagalee guddaa',
  'Vibrator': 'Raafamaa',
  'Power flex': 'Flex humnaa',
  'Want a quick tour of this page?': 'Daawwannaa saffisaa fuula kanaa?',
  'Show me': 'Natti agarsiisi',
  'Before': 'Dura',
  'After': 'Booda',
  'Allow screenshots': 'Suuraa iskiriinii hayyami',
  'Screenshot terms': 'Haala suuraa iskiriinii',
  'Screenshots are for your own use only, for example to remember a part or to send it to your technician.': 'Suuraan iskiriinii itti fayyadama mataa keetiif qofa, fkn kutaa yaadachuuf ykn ogeessa keetti erguuf.',
  'Publishing, reselling or editing them, or using our photos and prices elsewhere, needs our written permission.': 'Maxxansuun, irra deebiin gurguruun, gulaaluun ykn suuraa fi gatii keenya bakka biraatti fayyadamuun hayyama barreeffamaa keenya barbaada.',
  'Every screenshot carries our watermark with the date and your agreement number.': 'Suuraan iskiriinii hundi mallattoo bishaanii keenya guyyaa fi lakkoofsa waliigaltee kee waliin qaba.',
  'I agree to the screenshot terms': 'Haala suuraa iskiriinii nan fudhadha',
  'Screenshots allowed. Each one carries our watermark.': 'Suuraan iskiriinii hayyamameera. Tokkoon tokkoon mallattoo keenya qaba.',
  'All rights reserved': 'Mirgi hundi eegamaadha',
  'Captured on': 'Kan kaafame',
  'Agreement': 'Waliigaltee',
  'A part of this page stopped working.': 'Kutaan fuula kanaa hojii dhaabeera.',
  'A thank-you offer from the team': 'Dhiyeessii galateeffannaa garee irraa',
  'A tracking number for every box, door to door.': 'Lakkoofsa hordoffii saanduqa hundaaf, balbala hanga balbalaatti.',
