  'Hide the technical detail': 'Bal\'ina teeknikaa dhoksi',
  'How would you like to reach us?': 'Akkamitti nu quunnamuu barbaaddu?',
  'Insider': 'Keessummaa dhihoo',
  'Instant answers, any time of day': 'Deebii battalaa, yeroo kamiyyuu',
  'Invoice + packing list': 'Nagahee + tarree qindaa\'ina',
  'Invoice and packing list inside for customs.': 'Nagaheen fi tarreen qindaa\'inaa kastamiif keessa jiru.',
  'Legend': 'Seenaa',
  'Live chat on the website': 'Haasaa kallattii marsariitii irratti',
