  'Trying to get around this protection, for example by photographing or filming the screen with another phone, camera or device, or by using tools that hide or remove our watermark, is not allowed and can be punished under UAE law.': 'Eegumsa kana dabruuf yaaluun, fakkeenyaaf iskiriinii bilbila, kaameraa ykn meeshaa biraatiin suuraa ykn viidiyoo kaasuun, ykn meeshaalee mallattoo bishaanii keenya dhoksan ykn haqan fayyadamuun, hin hayyamamu; seera UAE tiin adabsiisa.',
  'Copying our design, colours, layout, structure, look, characters (including Samsoom), texts or ideas, or using them wrongly or falsely (for example to look like Sam Electronics or to suggest you work with us), is not allowed and can be punished under UAE law.': 'Dizaayinii, halluu, qindaa’ina, caasaa, bifa, gocha-taphattoota (Samsoom dabalatee), barreeffamoota ykn yaada keenya garagalchuun, ykn sirrii hin taaneen ykn sobaan fayyadamuun (fkn. akka Sam Electronics fakkaachuuf), hin hayyamamu; seera UAE tiin adabsiisa.',
